setup/nginx.conf<pre><code># Bottleneck: balanceamento de carga.
# O Nginx é o único serviço exposto (porta 8080 do host). Ele distribui as
# requisições entre as réplicas do gateway (round robin, o padrão do upstream).

user  nginx;
worker_processes  auto;

error_log  /var/log/nginx/error.log notice;
pid        /run/nginx.pid;

events {
    worker_connections  1024;
}

http {

    # DNS interno do Docker: com "resolve" (nginx &gt;= 1.27.3) o upstream é
    # re-resolvido a cada 10 s, então "docker compose up --scale gateway=N"
    # entra no balanceamento sem precisar de nginx -s reload
    resolver 127.0.0.11 valid=10s ipv6=off;

    upstream gateways {
        zone gateways 64k;
        server gateway:8080 resolve;
        # conexões reaproveitadas com o gateway (menos handshakes sob carga)
        keepalive 32;
    }

    log_format upstream '$remote_addr "$request" $status -&gt; $upstream_addr ($upstream_response_time s)';
    access_log /var/log/nginx/access.log upstream;

    server {
        listen 80;
        server_tokens off;

        # métricas e detalhes do actuator ficam só na rede interna
        # (o Prometheus fala direto com o gateway); o health fica público
        location = /gateway/actuator/health {
            proxy_pass http://gateways;
        }
        location /gateway/actuator {
            return 404;
        }

        location / {
            proxy_pass         http://gateways;
            proxy_http_version 1.1;
            proxy_set_header   Connection        "";
            proxy_set_header   Host              $host;
            proxy_set_header   X-Real-IP         $remote_addr;
            proxy_set_header   X-Forwarded-For   $proxy_add_x_forwarded_for;
            proxy_set_header   X-Forwarded-Proto $scheme;
        }
    }
}
</code></pre> <p>Pontos além do hands-on 7 do curso:</p> Diretiva Por quê <code>resolver 127.0.0.11</code> + <code>server gateway:8080 resolve</code> O Nginx re-resolve o DNS do Docker a cada 10 s. Com <code>docker compose up --scale gateway=N</code> as réplicas novas entram no balanceamento sem <code>nginx -s reload</code> (no hands-on o Nginx só resolve na inicialização). <code>keepalive 32</code> + <code>proxy_http_version 1.1</code> Reaproveita conexões com o gateway: menos handshakes TCP sob carga. <code>location /gateway/actuator { return 404; }</code> Métricas do actuator ficam só na rede interna (o Prometheus fala direto com o gateway). <code>log_format upstream</code> O access log mostra qual réplica (<code>$upstream_addr</code>) atendeu cada requisição.

k8s/lb.yaml<pre><code># Bottleneck: balanceamento de carga no EKS.
#
#   internet -&gt; ELB da AWS (Service type LoadBalancer)
#            -&gt; pods do Nginx (lb, 2 réplicas)
#            -&gt; Service gateway (ClusterIP) -&gt; pods do gateway (2+ réplicas)
#
# O Nginx é a única porta de entrada: gateway, auth, account e exchange são
# ClusterIP (camada confiável), como no compose.
apiVersion: v1
kind: ConfigMap
metadata:
  name: lb-configmap
data:
  nginx.conf: |
    worker_processes auto;
    pid /tmp/nginx.pid;
    error_log /dev/stderr notice;

    events {
        worker_connections 1024;
    }

    http {
        client_body_temp_path /tmp/client_temp;
        proxy_temp_path       /tmp/proxy_temp;
        fastcgi_temp_path     /tmp/fastcgi_temp;
        uwsgi_temp_path       /tmp/uwsgi_temp;
        scgi_temp_path        /tmp/scgi_temp;

        log_format upstream '$remote_addr "$request" $status -&gt; $upstream_addr ($upstream_response_time s)';
        access_log /dev/stdout upstream;

        # no k8s o Service "gateway" já é um IP virtual que distribui entre
        # os pods; o Nginx mantém conexões abertas com ele (keepalive)
        upstream gateways {
            server gateway:8080;
            keepalive 32;
        }

        server {
            listen 8080;
            server_tokens off;

            location = /lb/health {
                access_log off;
                return 200 "ok\n";
            }

            location = /gateway/actuator/health {
                proxy_pass http://gateways;
            }
            location /gateway/actuator {
                return 404;
            }

            location / {
                proxy_pass         http://gateways;
                proxy_http_version 1.1;
                proxy_set_header   Connection        "";
                proxy_set_header   Host              $host;
                proxy_set_header   X-Real-IP         $remote_addr;
                proxy_set_header   X-Forwarded-For   $proxy_add_x_forwarded_for;
                proxy_set_header   X-Forwarded-Proto $scheme;
            }
        }
    }
---
apiVersion: apps/v1
kind: Deployment
metadata:
  name: lb
  labels:
    app: lb
spec:
  replicas: 2
  selector:
    matchLabels:
      app: lb
  template:
    metadata:
      labels:
        app: lb
    spec:
      securityContext:
        runAsNonRoot: true
        runAsUser: 101
        runAsGroup: 101
        seccompProfile:
          type: RuntimeDefault
      containers:
        - name: nginx
          image: nginx:1.29-alpine
          ports:
            - containerPort: 8080
          readinessProbe:
            httpGet:
              path: /lb/health
              port: 8080
            periodSeconds: 5
          resources:
            requests:
              memory: "32Mi"
              cpu: "50m"
            limits:
              memory: "128Mi"
              cpu: "500m"
          securityContext:
            allowPrivilegeEscalation: false
            readOnlyRootFilesystem: true
            capabilities:
              drop: [ "ALL" ]
          volumeMounts:
            - name: config
              mountPath: /etc/nginx/nginx.conf
              subPath: nginx.conf
              readOnly: true
            - name: tmp
              mountPath: /tmp
      volumes:
        - name: config
          configMap:
            name: lb-configmap
        - name: tmp
          emptyDir: {}
---
apiVersion: v1
kind: Service
metadata:
  name: lb
spec:
  type: LoadBalancer
  selector:
    app: lb
  ports:
    - name: http
      protocol: TCP
      port: 80
      targetPort: 8080
